import{_ as a,o as t,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Parcel to MQTT","text":"Development discontinued","tagline":"Parcel Tracker is already much further along. We are therefore discontinuing development of Parcel to MQTT. The existing documentation remains available as an archive.","actions":[{"theme":"brand","text":"View Parcel Tracker","link":"https://github.com/SoerenKaiser99/parcel_tracker"},{"theme":"alt","text":"GitHub","link":"https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/parcel_to_mqtt"}]},"features":[{"icon":"📦","title":"Parcel status","details":"Parcel status, last event, destination and tracking number as Home Assistant entities."},{"icon":"🚚","title":"DHL and Hermes active","details":"DHL account parcel list, manual DHL tracking numbers and Hermes parcel tracking."},{"icon":"🧩","title":"Provider sections","details":"Grouped settings for DHL, Hermes, GLS, DPD, UPS, Amazon Logistics, Deutsche Post letters and FedEx."},{"icon":"📊","title":"Counters and slots","details":"Counters for total, in transit, out for delivery, pickup point, delivered, returning, exception and unknown."},{"icon":"🏠","title":"MQTT Discovery","details":"Home Assistant creates parcel, status and counter entities automatically."},{"icon":"🔔","title":"Automations","details":"Notifications are built through normal Home Assistant automations based on the generated entities."}]},"headers":[],"relativePath":"en/projects/parcel-to-mqtt/index.md","filePath":"en/projects/parcel-to-mqtt/index.md","lastUpdated":1793126212000}'),n={name:"en/projects/parcel-to-mqtt/index.md"};function o(s,e,l,c,p,d){return t(),r("div",null,[...e[0]||(e[0]=[i('<div class="warning custom-block"><p class="custom-block-title">Development discontinued</p><p>Parcel Tracker is already much further along. We are therefore discontinuing development of Parcel to MQTT and recommend taking a look at <a href="https://github.com/SoerenKaiser99/parcel_tracker" target="_blank" rel="noreferrer">Parcel Tracker by SoerenKaiser99</a>.</p><p>Source code and existing documentation remain available as an archive. The features and instructions below describe the final state of our package.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Parcel to MQTT is a Home Assistant app that publishes parcel tracking data through MQTT Discovery.</p><p>The current version uses DHL account parcel lists, optional manual DHL tracking numbers and Hermes parcel tracking. App settings are grouped by provider so the Home Assistant configuration stays compact as provider sections.</p><div class="info custom-block"><p class="custom-block-title">Origin</p><p>This implementation is adapted from and inspired by the ioBroker adapter <a href="https://github.com/TA2k/ioBroker.parcel" target="_blank" rel="noreferrer">TA2k/ioBroker.parcel</a>.</p><p>The shared status model is inspired by the MIT licensed Home Assistant parcel integrations <a href="https://github.com/ha-parcel-integrations" target="_blank" rel="noreferrer">ha-parcel-integrations</a>.</p></div><h2 id="former-provider-roadmap-archive" tabindex="-1">Former Provider Roadmap (Archive) <a class="header-anchor" href="#former-provider-roadmap-archive" aria-label="Permalink to &quot;Former Provider Roadmap (Archive)&quot;">​</a></h2><p>The following items describe the previous development state and earlier plans. This roadmap will no longer be implemented:</p><ul><li>DHL: active through <code>dhllogin://</code> browser login code plus optional manual tracking numbers</li><li>Amazon: prepared with e-mail, password and optional OTP token</li><li>Hermes: currently active by manual tracking number; account login with app username and app password is planned</li><li>UPS: prepared with app username, app password and manual tracking numbers</li><li>GLS: prepared with manual tracking numbers and delivery postal code; polling waits for a stable guest bearer session</li><li>DPD: prepared with username, password and manual tracking numbers after the stable login/session flow is mapped</li><li>Deutsche Post letters and FedEx: prepared with manual tracking numbers for later connectors</li></ul><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><ul><li><a href="./installation">Installation</a></li><li><a href="./configuration">Configuration</a></li><li><a href="./entities">Entities</a></li><li><a href="./examples">Examples</a></li></ul>',10)])])}const h=a(n,[["render",o]]);export{u as __pageData,h as default};
